import{_ as r,C as s,o as t,c,a6 as o,b as n,w as a,a as i,E as l,af as h}from"./chunks/framework.DIp0zHSV.js";const _=JSON.parse('{"title":"Shell Strategy","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/shell-strategy.md","filePath":"architecture/shell-strategy.md","lastUpdated":1794274588000}'),p={name:"architecture/shell-strategy.md"};function u(g,e,b,m,f,y){const d=s("Mermaid");return t(),c("div",null,[e[1]||(e[1]=o('<h1 id="shell-strategy" tabindex="-1">Shell Strategy <a class="header-anchor" href="#shell-strategy" aria-label="Permalink to &quot;Shell Strategy&quot;">​</a></h1><blockquote><p><strong><code>custom:lcars-shell</code></strong>: a Home Assistant dashboard strategy that generates a complete LCARS shell (frame, sidebars, header and footer, content panel) as one <code>custom:lcards-layout-view</code>, built from LCARdS cards only (plus auto-entities for the room light list). <strong>Source</strong>: <code>src/strategies/lcards-shell-strategy.js</code>, <code>src/cards/schemas/shell-strategy-schema.js</code>, registration in <code>src/lcards-main.js</code><strong>Test</strong>: <code>tests/docs/shell-strategy-output.test.js</code></p></blockquote><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>A dashboard strategy is a class Home Assistant asks for a dashboard config: the stored dashboard holds only <code>strategy: { type: ..., &lt;options&gt; }</code>, and the frontend calls the class&#39;s static <code>generate(config, hass)</code> each time the dashboard loads and uses the views it returns. Nothing generated is saved.</p><p>The LCARS shell strategy returns one view (<code>path: lcars</code>, type <code>custom:lcards-layout-view</code>) whose grid draws the LCARS frame. Its nested panels are <code>custom:lcards-layout-card</code>s, its chrome is <code>lcards-elbow</code> and <code>lcards-button</code> cards, navigation is an <code>lcards-select-menu</code>, and the content panel is a room light controller. The grid machinery it relies on (visibility-driven row sizing, media queries, per-area surfaces) is described in <a href="./layout-view.html">Layout View and Layout Card</a>.</p><p>The user-facing description is the strategy&#39;s entry in Home Assistant&#39;s New Dashboard picker (&quot;LCARS Dashboard&quot;) and its configure dialog; the docs mention it on <a href="./../cards/layout-view/">Layout View</a>, <a href="./../cards/select-menu/layout.html">Select Menu: Layout</a> (the sidebar pattern) and <a href="./../getting-started/lcars-patterns.html">LCARS Patterns</a>. The published schema is in <code>lcards-schema.json</code> (<a href="./../getting-started/ai-assistance.html">AI Assistance</a>).</p><hr><h2 id="registration" tabindex="-1">Registration <a class="header-anchor" href="#registration" aria-label="Permalink to &quot;Registration&quot;">​</a></h2><p><code>src/lcards-main.js</code> does three things at <strong>module top level</strong> (not inside the async core initialization), because Home Assistant waits at most 5 s (<code>MAX_WAIT_STRATEGY_LOAD</code> in the frontend&#39;s <code>get-strategy.ts</code>) for a strategy element before it fails the dashboard:</p><table tabindex="0"><thead><tr><th>What</th><th>Code</th></tr></thead><tbody><tr><td>The strategy element</td><td><code>customElements.define(&#39;ll-strategy-dashboard-lcars-shell&#39;, LCARdSShellDashboardStrategy)</code></td></tr><tr><td>Its configure form</td><td><code>customElements.define(&#39;lcards-shell-strategy-editor&#39;, LCARdSShellStrategyEditor)</code></td></tr><tr><td>The picker entry</td><td><code>window.customStrategies.push({ type: &#39;lcars-shell&#39;, strategyType: &#39;dashboard&#39;, name: &#39;LCARS Dashboard&#39;, description, documentationURL })</code>, guarded against a second push</td></tr></tbody></table><p>Home Assistant turns <code>strategy.type: custom:lcars-shell</code> of a dashboard into the tag <code>ll-strategy-dashboard-lcars-shell</code> (it also accepts the legacy <code>ll-strategy-lcars-shell</code>). The New Dashboard dialog lists <code>window.customStrategies</code> entries of <code>strategyType: &#39;dashboard&#39;</code> and creates <code>{ strategy: { type: &#39;custom:lcars-shell&#39; } }</code> for this one.</p><p><code>LCARdSShellDashboardStrategy</code> (extends <code>HTMLElement</code>; only its statics are used):</p><table tabindex="0"><thead><tr><th>Static</th><th>Value</th></tr></thead><tbody><tr><td><code>configRequired</code></td><td><code>true</code>: creating the dashboard opens the configure dialog first</td></tr><tr><td><code>getCreateSuggestions(hass)</code></td><td><code>{ title: &#39;LCARS&#39;, icon: &#39;mdi:view-dashboard-variant&#39; }</code> for the new dashboard&#39;s title and icon</td></tr><tr><td><code>getConfigElement()</code></td><td><code>document.createElement(&#39;lcards-shell-strategy-editor&#39;)</code></td></tr><tr><td><code>generate(config, hass)</code></td><td><code>Promise&lt;{ views: [shellView] }&gt;</code></td></tr></tbody></table><hr><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>The schema (<code>shellStrategySchema</code>, <code>additionalProperties: false</code>) is the single source of the options. <code>shellStrategyEditorSchema()</code> derives the configure dialog&#39;s <code>ha-form</code> schema from it (name, <code>title</code> as label, <code>description</code> as helper, the <code>x-ui-hints.selector</code>), so the form and the published schema cannot drift. <code>scripts/lib/card-schemas.js</code> registers it with <code>kind: &#39;strategy&#39;</code> for the published schema and the config checker; the doc example validator skips strategies, because doc examples never contain a dashboard <code>strategy:</code> block.</p><table tabindex="0"><thead><tr><th>Key</th><th>Selector</th><th>What it does</th></tr></thead><tbody><tr><td><code>type</code></td><td></td><td><code>custom:lcars-shell</code> (required)</td></tr><tr><td><code>room_selector_entity</code></td><td><code>input_select</code>, <code>select</code> or <code>input_text</code></td><td>Chooses the content panel mode (see below); blank shows a placeholder</td></tr><tr><td><code>page_selector_entity</code></td><td><code>input_select</code>, <code>select</code></td><td>The sidebar select menu&#39;s entity; blank shows a placeholder button</td></tr><tr><td><code>top_bar_entity</code></td><td><code>input_boolean</code></td><td>Shows or hides the header bar row; also the entity of the first header-left button</td></tr><tr><td><code>right_sidebar_entity</code></td><td><code>input_boolean</code></td><td>Shows or hides the right sidebar; also the entity of the second header-left button</td></tr></tbody></table><p><code>LCARdSShellStrategyEditor</code> is a small <code>LitElement</code>: <code>setConfig(config)</code> stores the strategy config, and an <code>ha-form</code> <code>value-changed</code> is re-dispatched as <code>config-changed</code> with the new values. Home Assistant calls <code>generate()</code> again with them.</p><hr><h2 id="generation" tabindex="-1">Generation <a class="header-anchor" href="#generation" aria-label="Permalink to &quot;Generation&quot;">​</a></h2>',21)),(t(),n(h,null,{default:a(()=>[l(d,{id:"mermaid-204",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20G%5B%22generate(config%2C%20hass)%22%5D%20--%3E%20E%5B%22read%20room_selector_entity%2C%20page_selector_entity%2C%3Cbr%2F%3Etop_bar_entity%2C%20right_sidebar_entity%20(blank%3A%20null)%22%5D%0A%20%20%20%20E%20--%3E%20Q%7B%22room_selector_entity%20set%3Cbr%2F%3Eand%20in%20hass.states%3F%22%7D%0A%20%20%20%20Q%20--%20no%20--%3E%20P%5B%22_contentPlaceholderCard()%3Cbr%2F%3Eoutline%20button%20with%20a%20setup%20hint%22%5D%0A%20%20%20%20Q%20--%20yes%20--%3E%20D%7B%22domain%22%7D%0A%20%20%20%20D%20--%20input_text%20--%3E%20A%7B%22hass.areas%20has%20areas%3F%22%7D%0A%20%20%20%20A%20--%20yes%20--%3E%20AA%5B%22_autoAreasRoomCard(areas%20sorted%20by%20name%2C%20entity)%3Cbr%2F%3Eauto-areas%20mode%22%5D%0A%20%20%20%20A%20--%20no%20--%3E%20P2%5B%22_contentPlaceholderCard('No%20areas%20found%20...')%22%5D%0A%20%20%20%20D%20--%20%22input_select%20%2F%20select%22%20--%3E%20R%5B%22_roomLightControllerCard(entity)%3Cbr%2F%3Eentity%20mode%22%5D%0A%20%20%20%20P%20--%3E%20V%5B%22_buildShellView(contentCard%2C%20%7B%20pageEntity%2C%20topBarEntity%2C%20rightSidebarEntity%20%7D)%22%5D%0A%20%20%20%20P2%20--%3E%20V%0A%20%20%20%20AA%20--%3E%20V%0A%20%20%20%20R%20--%3E%20V%0A%20%20%20%20V%20--%3E%20O%5B%22return%20%7B%20views%3A%20%5Bview%5D%20%7D%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o(`<p><code>generate()</code> reads <code>hass.states</code> and <code>hass.areas</code> once. A new area, or a changed helper, shows up the next time Home Assistant generates the dashboard (a reload, or a change in the configure dialog).</p><h3 id="content-panel-modes" tabindex="-1">Content panel modes <a class="header-anchor" href="#content-panel-modes" aria-label="Permalink to &quot;Content panel modes&quot;">​</a></h3><p>Both room controllers are a <code>lcards-layout-card</code> in the <code>content-panel</code> area (<code>view_layout.margin: &#39;20&#39;</code>), with a header elbow, a selector column (a select menu plus a <code>panel-light</code> filler), a scrollable light list and a footer elbow:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Room list</th><th>Selection stored in</th><th>Light list</th></tr></thead><tbody><tr><td>Entity (<code>input_select</code> / <code>select</code>)</td><td>The entity&#39;s own options (the select menu reads them)</td><td>The entity (the select menu&#39;s default action)</td><td><code>custom:auto-entities</code> with a Jinja2 filter over <code>area_entities(states(entity))</code>, one <code>lcards-slider</code> (<code>pills-left-border</code>, <code>match-light</code> gradient, toggle and more-info actions) per light, inside a single-column <code>lcards-layout-card</code></td></tr><tr><td>Auto-areas (<code>input_text</code>)</td><td><code>hass.areas</code>, as explicit select menu <code>options</code> (<code>value: area_id</code>, <code>label: name</code>, <code>icon</code>)</td><td>The <code>input_text</code>, through each option&#39;s <code>tap_action</code> (<code>input_text.set_value</code>; <code>select_option</code> for the select domains)</td><td>The same auto-entities list on the <code>input_text</code>&#39;s state</td></tr><tr><td>Placeholder</td><td></td><td></td><td>An <code>outline</code> button with a hint</td></tr></tbody></table><p>The light list needs the auto-entities card from HACS; without it Home Assistant shows its &quot;custom element doesn&#39;t exist&quot; error card in that cell.</p><h3 id="the-shell-view" tabindex="-1">The shell view <a class="header-anchor" href="#the-shell-view" aria-label="Permalink to &quot;The shell view&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;header-border  header-border  header-border  header-border  header-border  header-border  header-border  header-border&quot;</span></span>
<span class="line"><span>&quot;border-left    header-left    .              header         header         header         header         sidebar-right&quot;</span></span>
<span class="line"><span>&quot;border-left    header-left    .              .              .              .              .              sidebar-right&quot;</span></span>
<span class="line"><span>&quot;border-left    header-left    .              content-panel  content-panel  content-panel  .              sidebar-right&quot;</span></span>
<span class="line"><span>&quot;sidebar-left   sidebar-left   .              content-panel  content-panel  content-panel  .              sidebar-right&quot;</span></span>
<span class="line"><span>&quot;footer-left    footer-left    footer-left    content-panel  content-panel  content-panel  .              sidebar-right&quot;</span></span>
<span class="line"><span>&quot;footer-left    footer-left    footer-left    .              .              .              .              sidebar-right&quot;</span></span>
<span class="line"><span>&quot;footer-left    footer-left    footer-left    .              footer         footer         footer         sidebar-right&quot;</span></span>
<span class="line"><span>&quot;footer-left    footer-left    footer-left    .              footer-border  footer-border  footer-border  sidebar-right&quot;</span></span></code></pre></div><ul><li><strong>Tracks.</strong> Columns <code>45px clamp(100px, 12vw, 180px) 5px 40px 1fr 40px 5px minmax(0, auto)</code>; rows <code>&lt;header-border&gt; clamp(25px, 5vh, 95px) 5px 40px 1fr 40px 5px clamp(25px, 5vh, 95px) 45px</code>, where the first row is <code>minmax(0,auto)</code> with a <code>top_bar_entity</code> and <code>0px</code> without one (a definite <code>0px</code>, so the view&#39;s row measurement cannot mistake it for free space). <code>layout.height</code> is <code>calc(100dvh - var(--header-height, 56px))</code>; <code>grid-gap</code> 5px, no margins or padding.</li><li><strong>Narrow screens.</strong> <code>layout.mediaquery[&#39;(max-width: 1010px)&#39;]</code> narrows the column before the right sidebar to 1px.</li><li><strong>Surfaces.</strong> <code>layout.areas[&#39;content-panel&#39;]</code> sets a 20px margin.</li></ul><table tabindex="0"><thead><tr><th>Area</th><th>Cards</th></tr></thead><tbody><tr><td><code>header-border</code></td><td>Only with <code>top_bar_entity</code>: a <code>lcards-layout-card</code> (<code>height: 10vh</code>) with a segmented <code>header-left</code> elbow and a two-row banner (a <code>panel-light</code> strip and a text button), with <code>visibility: state on</code> of <code>top_bar_entity</code>; the view&#39;s visibility row sizing then writes that row as <code>10vh</code> or <code>0px</code></td></tr><tr><td><code>header-left</code></td><td>An <code>lcards-alert-overlay</code> (<code>dismiss_mode: dismiss</code>, blur backdrop, no canvas; visible only during an alert) and a <code>lcards-layout-card</code> with two <code>panel-dark</code> buttons on <code>top_bar_entity</code> and <code>right_sidebar_entity</code> (their default tap action toggles them)</td></tr><tr><td><code>border-left</code></td><td>A <code>panel-light</code> strip button</td></tr><tr><td><code>header</code></td><td>An <code>outline</code> button labelled &quot;header&quot;</td></tr><tr><td><code>sidebar-left</code></td><td>A 2 by 2 <code>lcards-layout-card</code>: <code>panel-light</code> strips in the 45px column, the page <code>lcards-select-menu</code> (<code>grid.height: fit</code>, so it publishes a definite height for the <code>minmax(0, max-content)</code> row) or a placeholder button, and a <code>panel-dark</code> filler in the <code>minmax(40px, 1fr)</code> row. The strips and the filler set <code>min_height: 1</code>, so they do not paint past a collapsed row</td></tr><tr><td><code>content-panel</code></td><td>The room controller or the placeholder</td></tr><tr><td><code>sidebar-right</code></td><td>An <code>outline</code> button (<code>width: clamp(100px,16vw,230px)</code>), with <code>visibility: state on</code> of <code>right_sidebar_entity</code> when set</td></tr><tr><td><code>footer-left</code></td><td>A segmented <code>footer-left</code> elbow (<code>outer_curve: 160</code>, <code>inner_curve: 115</code>, <code>var(--lcars-ui-primary)</code> / <code>var(--lcars-ui-quaternary)</code>)</td></tr><tr><td><code>footer</code></td><td>A <code>lcards-layout-card</code> with two <code>filled</code> toggle buttons (the second pulses on hover)</td></tr><tr><td><code>footer-border</code></td><td>A <code>lcards-layout-card</code> with one <code>panel-light</code> button</td></tr></tbody></table><p>The sizing choices (definite heights for content-sized tracks, <code>minmax(0, ...)</code> tracks, <code>min_height: 1</code> fillers) follow the rules in <code>.github/instructions/cards.instructions.md</code>, &quot;Sizing in Nested Grids&quot;.</p><hr><h2 id="editing-a-strategy-dashboard" tabindex="-1">Editing a strategy dashboard <a class="header-anchor" href="#editing-a-strategy-dashboard" aria-label="Permalink to &quot;Editing a strategy dashboard&quot;">​</a></h2><p>Because the views are generated, the layout view&#39;s own editor cannot save into them. Opening edit mode on a strategy dashboard makes Home Assistant show its strategy editor dialog (<code>hui-root</code> <code>_enableEditMode()</code> calls <code>showDashboardStrategyEditorDialog()</code>), which hosts <code>lcards-shell-strategy-editor</code> for the options and offers <strong>Take control</strong>: that saves the generated config as an ordinary dashboard, after which the strategy no longer runs and the view is edited like any other layout view.</p><hr><h2 id="adding-an-option" tabindex="-1">Adding an option <a class="header-anchor" href="#adding-an-option" aria-label="Permalink to &quot;Adding an option&quot;">​</a></h2><p>A new strategy option follows the <code>lcards-card-option</code> skill: add it to <code>shellStrategySchema</code> with a <code>title</code>, a <code>description</code> and an <code>x-ui-hints.selector</code> (the form picks it up), read it in <code>generate()</code>, and extend <code>tests/docs/shell-strategy-output.test.js</code>, which runs the config checker over every generated variant and expects no errors or warnings.</p><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./layout-view.html">Layout View and Layout Card</a></li><li><a href="./cards/lcards-card-foundation.html">Card Foundation</a></li><li><a href="./systems-arch.html">Systems Architecture</a></li><li>Home Assistant developer docs: <a href="https://developers.home-assistant.io/docs/frontend/custom-ui/custom-strategy/" target="_blank" rel="noreferrer">Custom strategies</a></li></ul>`,19))])}const v=r(p,[["render",u]]);export{_ as __pageData,v as default};
